from .ui_strings import D

def F(fid, t, d, h, e):
    """t,d,h are (en, fa, zh); e is a language-neutral example string."""
    for suffix, val in (("t", t), ("d", d), ("h", h)):
        D[f"field.{fid}.{suffix}"] = val
    D[f"field.{fid}.e"] = (e, e, e)

